import React from "react";
import { screen, render, fireEvent, createEvent } from "@testing-library/react";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import * as stories from "./SlideIndicator.stories";
import SlideIndicator, { ProgressIndicator } from "./SlideIndicator";
import ConsoleSpy from "../../lib/tests/ConsoleSpy";

const { Basic } = composeStories(stories) as any;

describe("SlideIndicator component", () => {
  let consoleSpy = ConsoleSpy();

  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("is retrocompatible with deprecated names", () => {
    const { container } = render(<ProgressIndicator total={6} />);
    expect(container).toMatchSnapshot();
    expect(consoleSpy.warn).toHaveBeenCalledTimes(1);
    expect(consoleSpy.warn.mock.calls[0][0]).toMatch(/AIRBUS-DS/);
  });

  it("shows all when 7 items are present", () => {
    render(<SlideIndicator total={7} />);
    const visibleSteps = screen.getAllByRole("tab");
    expect(visibleSteps).toHaveLength(7);
  });

  it("shows correct index is passed on click", () => {
    const onStepClick = jest.fn();
    render(<SlideIndicator total={7} onStepClick={onStepClick} />);
    const steps = screen.getAllByRole("tab");
    expect(steps).toHaveLength(7);
    fireEvent.click(steps[3]);
    expect(onStepClick).toBeCalledWith(expect.anything(), 3);
    expect(onStepClick).toBeCalledTimes(1);
  });

  it("reduce the size at the right when left side is selected and total more than 7", () => {
    render(<SlideIndicator total={10} selected={1} />);
    const visibleSteps = screen.getAllByRole("tab");
    expect(visibleSteps[0]).not.toHaveClass("ds-slideindicator-step--end");
    expect(visibleSteps[5]).toHaveClass("ds-slideindicator-step--beforeend");
    expect(visibleSteps[6]).toHaveClass("ds-slideindicator-step--end");
  });

  it("reduce the size at the left when right side is selected and total more than 7", () => {
    render(<SlideIndicator total={10} selected={9} />);
    const visibleSteps = screen.getAllByRole("tab");
    expect(visibleSteps[3]).toHaveClass("ds-slideindicator-step--end");
    expect(visibleSteps[4]).toHaveClass("ds-slideindicator-step--beforeend");
    expect(visibleSteps[9]).not.toHaveClass("ds-slideindicator-step--end");
  });

  it("shows the steps vertically", () => {
    render(
      <SlideIndicator
        total={10}
        selected={1}
        orientation="vertical"
        data-testid="progressindicator"
      />
    );
    const component = screen.getByTestId("progressindicator");
    expect(component).toHaveClass("ds-slideindicator--vertical");
  });

  describe("Keyboard Navigation", () => {
    it("navigates horizontally with ArrowRight and ArrowLeft", () => {
      const onStepClick = jest.fn();
      render(
        <SlideIndicator total={5} selected={2} onStepClick={onStepClick} />
      );
      const currentTab = screen.getByRole("tab", { name: "step 2" });

      // Test Right
      fireEvent.keyDown(currentTab, { key: "ArrowRight" });
      expect(onStepClick).toHaveBeenLastCalledWith(expect.anything(), 3);

      // Test Left
      fireEvent.keyDown(currentTab, { key: "ArrowLeft" });
      expect(onStepClick).toHaveBeenLastCalledWith(expect.anything(), 1);
    });

    it("navigates vertically with ArrowDown and ArrowUp", () => {
      const onStepClick = jest.fn();
      render(
        <SlideIndicator
          total={5}
          selected={2}
          orientation="vertical"
          onStepClick={onStepClick}
        />
      );
      const currentTab = screen.getByRole("tab", { name: "step 2" });

      // Test Down (Next)
      fireEvent.keyDown(currentTab, { key: "ArrowDown" });
      expect(onStepClick).toHaveBeenLastCalledWith(expect.anything(), 3);

      // Test Up (Prev)
      fireEvent.keyDown(currentTab, { key: "ArrowUp" });
      expect(onStepClick).toHaveBeenLastCalledWith(expect.anything(), 1);
    });

    it("prevents default scrolling behavior on navigation keys", () => {
      const onStepClick = jest.fn();
      render(
        <SlideIndicator total={5} selected={2} onStepClick={onStepClick} />
      );
      const currentTab = screen.getByRole("tab", { name: "step 2" });

      // Create a specific event to check if preventDefault is called
      const event = createEvent.keyDown(currentTab, { key: "ArrowRight" });
      fireEvent(currentTab, event);

      expect(event.defaultPrevented).toBe(true);
      expect(onStepClick).toHaveBeenCalled();
    });

    it("does not trigger navigation at boundaries", () => {
      const onStepClick = jest.fn();
      const { rerender } = render(
        <SlideIndicator total={5} selected={0} onStepClick={onStepClick} />
      );

      // At index 0, Left Arrow should do nothing
      const firstTab = screen.getByRole("tab", { name: "step 0" });
      fireEvent.keyDown(firstTab, { key: "ArrowLeft" });
      expect(onStepClick).not.toHaveBeenCalled();

      // At last index, Right Arrow should do nothing
      rerender(
        <SlideIndicator total={5} selected={4} onStepClick={onStepClick} />
      );
      const lastTab = screen.getByRole("tab", { name: "step 4" });
      fireEvent.keyDown(lastTab, { key: "ArrowRight" });
      expect(onStepClick).not.toHaveBeenCalled();
    });

    it("ignores unrelated keys", () => {
      const onStepClick = jest.fn();
      render(
        <SlideIndicator total={5} selected={2} onStepClick={onStepClick} />
      );
      const currentTab = screen.getByRole("tab", { name: "step 2" });

      const event = createEvent.keyDown(currentTab, { key: "Enter" });
      fireEvent(currentTab, event);

      // Should NOT prevent default for non-nav keys
      expect(event.defaultPrevented).toBe(false);
      expect(onStepClick).not.toHaveBeenCalled();
    });
  });
});
